class Note(BaseModel):
    text: str = Field(min_length=1)

# typed version
@app.put("/notes/{note_id}")
async def save(note_id: str, note: Note, dry_run: bool = False):
    return {"note_id": note_id, "dry_run": dry_run, "text": note.text}

# the version the AI wrote
@app.put("/ai/notes/{note_id}")
async def save_ai(request: Request, note_id: str, note: Note):
    dry_run = request.query_params.get("dry_run")
    if dry_run:
        return {"mode": "dry run, nothing saved"}
    return {"mode": "saved"}
